def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if a string is palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Generate palindrome by mirroring left to right
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    # Increment the "left half" (and middle if odd) as a number and return it as string
    def increment_left(left: str) -> str:
        left_num = int(left)
        left_num += 1
        return str(left_num)

    # If all digits are '9', next palindrome is 10..01 with length+1 digits
    if set(s) == {'9'}:
        return int('1' + ('0' * (length - 1)) + '1')

    odd_length = (length % 2 != 0)
    mid = length // 2

    # Split the number into left half and right half
    if odd_length:
        left = s[:mid+1]  # includes middle digit
        right = s[mid+1:]
    else:
        left = s[:mid]
        right = s[mid:]

    # Construct palindrome from left half
    palindrome = make_palindrome(left, odd_length)
    palindrome_num = int(palindrome)

    # If palindrome is strictly greater than n, return it
    if palindrome_num > n:
        return palindrome_num

    # Otherwise increment the left half and form palindrome again
    # Increment the left half as integer
    left_inc = increment_left(left)

    # Handle the case that incrementing left changes length (e.g. 999 -> 1000)
    if len(left_inc) > len(left):
        # This means length increased, so palindrome length increases by 1 or 2
        # For example 999 -> after increment left = 1000, length increased by 1
        # The next palindrome is 10...01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = make_palindrome(left_inc, odd_length)
    return int(palindrome)

