def min_Jumps(d: int, step: int) -> int:
    d = abs(d)
    if d == 0:
        return 0
    if d == step:
        return 1
    if d < step:
        # One step overshoot, can adjust direction to land exactly at (d,0)
        return 2

    # If d > step:
    jumps = d // step
    if d % step == 0:
        return jumps
    else:
        # Check if can reach exactly with jumps or jumps+1 or jumps+2 steps
        # We try jumps+1:
        total_dist = (jumps + 1) * step
        if total_dist >= d and (total_dist ** 2 - d ** 2) ** 0.5 <= (jumps + 1) * step:
            # Because any point at distance total_dist can be placed anywhere on circle,
            # and we want x=d, so y² = total_dist² - d² must be achievable (always true)
            return jumps + 1
        else:
            # Else 2 more steps are enough (known fact)
            return jumps + 2

